import{_ as t,o as r,c as e,a2 as l}from"./chunks/framework.F7eQ-ohH.js";const h=JSON.parse('{"title":"工程问题概念","description":"","frontmatter":{},"headers":[],"relativePath":"行测/数量分析/7.工程问题.md","filePath":"行测/数量分析/7.工程问题.md","lastUpdated":1788883925000}'),i={name:"行测/数量分析/7.工程问题.md"};function o(c,a,n,p,s,f){return r(),e("div",null,[...a[0]||(a[0]=[l('<h1 id="工程问题概念" tabindex="-1">工程问题概念 <a class="header-anchor" href="#工程问题概念" aria-label="Permalink to &quot;工程问题概念&quot;">​</a></h1><p>相信大家在小学阶段都接触过这类基础应用题：小明 1 小时能做 8 个零件，小华 1 小时能做 10 个零件，小明每小时比小华少做多少个零件？这便是工程问题的雏形 —— 本质上，<strong>行测考试中的工程问题，就是围绕工作量、工作时间和工作效率展开的数量关系计算题</strong>，核心逻辑与基础应用题完全一致。</p><h2 id="常见概念" tabindex="-1">常见概念 <a class="header-anchor" href="#常见概念" aria-label="Permalink to &quot;常见概念&quot;">​</a></h2><ul><li><strong>工作量</strong>：衡量工作任务的总量，通常将整体工作设为 “1”（如完成整项工程记为 1），部分工作按占比用分数表示（如完成工程的 2/5，即工作量为 2/5）。</li><li><strong>工作效率</strong>：反映单位时间内完成的工作量，体现工作进度快慢。单位时间可根据题目情境设定（如小时、天、周等），效率单位为 “工作量 / 单位时间”（无歧义时可省略单位）。</li><li><strong>工作时间</strong>：完成指定工作量所需的时间，与效率成反比关系。</li></ul><h2 id="核心公式" tabindex="-1">核心公式 <a class="header-anchor" href="#核心公式" aria-label="Permalink to &quot;核心公式&quot;">​</a></h2><ul><li>工作量 = 工作效率 × 工作时间</li><li>工作效率 = 工作量 ÷ 工作时间</li><li>工作时间 = 工作量 ÷ 工作效率</li><li>总工作量 = 各分工作量之和（多人协作或分阶段工作时适用）</li></ul><h1 id="三种常见工程问题" tabindex="-1">三种常见工程问题 <a class="header-anchor" href="#三种常见工程问题" aria-label="Permalink to &quot;三种常见工程问题&quot;">​</a></h1><h2 id="同时合作型" tabindex="-1">同时合作型 <a class="header-anchor" href="#同时合作型" aria-label="Permalink to &quot;同时合作型&quot;">​</a></h2><p>当多个工作主体同时参与任务（如甲、乙两队同时修路，两根进水管同时注水），核心解题思路是<strong>先求合作总效率，再结合总工作量计算时间</strong>。为简化计算，通常将总工作量设为各主体单独完成时间的最小公倍数。</p><p>例：某工程项目，由甲项目公司单独做需4天才能完成，由乙项目公司单独做需6天才能完成，甲、乙、丙三个公司共同做2天就可完成。现因交工日期在即，需多公司合作，但甲公司因故退出，则由乙、丙公司合作完成此项目共需多少天?</p><p>A.3</p><p>B.4</p><p>C.5</p><p>D.6</p><p>解析：设工作总量为12(4、6、2 的最小公倍数)，则甲、乙的效率分别为3、2，甲乙、丙的合作效率为6，丙的效率为6-3-2=1。故所求为12÷(2+1)=4天。</p><h2 id="交替合作型" tabindex="-1">交替合作型 <a class="header-anchor" href="#交替合作型" aria-label="Permalink to &quot;交替合作型&quot;">​</a></h2><p><strong>交替合作是指工作主体按照一定的顺序轮流进行工作来完成任务，像甲和乙轮流挖隧道</strong>。首先还是要根据工作时间找到合适的工作总量（一般是工作时间的最小公倍数），计算出每个工作主体的工作效率。接着分析轮流工作的周期，一个周期内完成的工作量是各个工作主体在一个周期内工作量的总和。通过计算完整周期数以及剩余工作量，进而确定完成整个工作所需的总时间。这种类型的难点在于对轮流工作过程的分析，要清楚每个周期的工作量以及剩余工作量如何分配给不同的工作主体。</p><p>例：某游泳馆内有甲丙两个进水管和乙丁两个排水管，单开进水管向空池注水，甲需3小时，丙需5小时;单开排水管将满池的水放空，乙需4小时，丁需6小时，现池内有1/6的水，如果按照甲、乙、丙、丁的顺序轮流各开一个小时，那么经过多少小时后水池的水开始溢出?</p><p>A.4.5小时 15 分钟</p><p>B.10 小时 45分钟</p><p>C.15 小时 15 分钟</p><p>D.20 小时 45分钟</p><p>解析：要解决这个问题，我们需要按照甲、乙、丙、丁的顺序轮流各开1小时，计算水池从1/6满开始到首次溢出所需的时间。</p><ol><li>计算每个水管的工作效率甲进水管：每小时注水1/3池；丙进水管：每小时注水1/5池；乙排水管：每小时放水1/4池；丁排水管：每小时放水1/6池。</li><li>确定每个周期（4小时）的净注水量，一个周期内，四个水管各开1小时，总注水量为： $$\\frac{1}{3} - \\frac{1}{4} + \\frac{1}{5} - \\frac{1}{6} = \\frac{20}{60} - \\frac{15}{60} + \\frac{12}{60} - \\frac{10}{60} = \\frac{7}{60} \\text{池}$$</li><li>分析水池水位变化规律；初始水位：1/6池（即10/60池）。每个周期后水位增加：7/60池。需达到的溢出水位：1池（即60/60池）。</li><li>计算临界周期数 设经过 n 个周期后，水池水位接近但未超过 $$ 1 - \\frac{1}{3} = \\frac{2}{3} 池$$（因为甲管1小时注水1/3池，若超过此水位，甲管注水后会溢出）。</li><li>计算剩余水量及时间 4个周期后水位：38/60池。 进入第5个周期： 甲管注水1小时： $$\\frac{38}{60} + \\frac{20}{60} = \\frac{58}{60} \\text{池} $$（未溢出）。 乙管排水1小时： $$\\frac{58}{60} - \\frac{15}{60} = \\frac{43}{60} \\text{池}$$。 丙管注水1小时： $$\\frac{43}{60} + \\frac{12}{60} = \\frac{55}{60} \\text{池}$$。 丁管排水1小时： $$ \\frac{55}{60} - \\frac{10}{60} = \\frac{45}{60} \\text{池}$$。 进入第6个周期：甲管注水：需注水量为 $$1 - \\frac{45}{60} = \\frac{15}{60} \\text{池}$$，所需时间为： $$ \\frac{15/60}{1/3} = \\frac{3}{4} \\text{小时} = 45 \\text{分钟}$$</li><li>总时间计算 前5个周期： $$5 \\times 4 = 20$$ 小时。第6周期甲管注水：45分钟。总时间：20小时45分钟。答案：D. 20小时45分钟</li></ol><h1 id="真题示例" tabindex="-1">真题示例 <a class="header-anchor" href="#真题示例" aria-label="Permalink to &quot;真题示例&quot;">​</a></h1><p>【例1：一个工程的实施有甲、乙、丙三个工程队可供选择。已知甲、乙、丙的效率比为5∶4∶3。如果由甲单独实施所用时间比由乙单独实施所用时间少6天。问三个工程队共同实施多少天可以完成? A.10 B.11 C.12 D.13 答案：A 解析：设甲、乙、丙的效率分别为5、4、3，乙单独完成这项工程用时t天，则甲单独完成这项工程需要t-6天，则有5×(t-6)=4t，解得t=30，工作总量为4×30=120，三个工程队共同实施需要120÷(5+4+3)=10天。 】</p><p>【例2：建筑队计划150天建好大楼，按此效率工作30天后由于购买新型设备，工作效率提高20%，则大楼可以提前( )天完工。 A.20 B.25 C.30 D.45 答案：A 解析：设原计划的效率为1，则提高后的效率为1.2，总工作量为150，则有150=30+1.2t，解得t=100，故可以提前150-130=20天完工。 】</p>',27)])])}const d=t(i,[["render",o]]);export{h as __pageData,d as default};
